solution.solution.rs:
trait Filter {
    fn apply(&self, text: &str) -> String;
    fn name(&self) -> String;
}

struct Trim;
struct Upper;
struct Replace {
    from: String,
    to: String,
}
struct MaxLen(usize);

impl Filter for Trim {
    fn apply(&self, text: &str) -> String { text.split_whitespace().collect::<Vec<_>>().join(" ") }
    fn name(&self) -> String { "trim".into() }
}

impl Filter for Upper {
    fn apply(&self, text: &str) -> String { text.to_uppercase() }
    fn name(&self) -> String { "upper".into() }
}

impl Filter for Replace {
    fn apply(&self, text: &str) -> String { text.replace(&self.from, &self.to) }
    fn name(&self) -> String { format!("replace({}->{})", self.from, self.to) }
}

impl Filter for MaxLen {
    fn apply(&self, text: &str) -> String {
        if text.chars().count() <= self.0 {
            return text.to_string();
        }
        let mut out = String::new();
        for (i, c) in text.chars().enumerate() {
            if i + 1 >= self.0 {
                break;
            }
            out.push(c);
        }
        out.push('…');
        out
    }
    fn name(&self) -> String { format!("maxlen({})", self.0) }
}

struct Pipeline {
    filters: Vec<Box<dyn Filter>>,
}

impl Pipeline {
    fn new() -> Self {
        Pipeline { filters: Vec::new() }
    }

    fn add(mut self, f: Box<dyn Filter>) -> Self {
        self.filters.push(f);
        self
    }

    fn run(&self, text: &str) -> String {
        let mut text = text.to_string();
        for f in &self.filters {
            text = f.apply(&text);
        }
        text
    }

    fn describe(&self) -> String {
        if self.filters.is_empty() {
            return "empty".into();
        }
        self.filters.iter().map(|f| f.name()).collect::<Vec<_>>().join(" > ")
    }
}

impl Filter for Pipeline {
    fn apply(&self, text: &str) -> String { self.run(text) }
    fn name(&self) -> String { format!("pipeline[{}]", self.describe()) }
}

unitTests:
test("single filters", || {
    check_eq(Trim.apply("  too   many  spaces "), "too many spaces");
    check_eq(Upper.apply("crab"), "CRAB");
    check_eq(Replace { from: "teh".into(), to: "the".into() }.apply("teh cat"), "the cat");
    check_eq(MaxLen(5).apply("abcdefgh"), "abcd…");
    check_eq(MaxLen(5).apply("abc"), "abc");
});

test("a pipeline", || {
    let p = Pipeline::new()
        .add(Box::new(Trim))
        .add(Box::new(Replace { from: "teh".into(), to: "the".into() }))
        .add(Box::new(Upper));
    check_eq(p.run("  teh   quick fox "), "THE QUICK FOX");
    check_eq(p.describe(), "trim > replace(teh->the) > upper");
    check_eq(Pipeline::new().describe(), "empty");
    check_eq(Pipeline::new().run("same"), "same");
});

test("pipelines inside pipelines", || {
    let inner = Pipeline::new().add(Box::new(Trim)).add(Box::new(Upper));
    let outer = Pipeline::new().add(Box::new(inner)).add(Box::new(MaxLen(6)));
    check_eq(outer.run("  hello   world "), "HELLO…");
    check_eq(outer.describe(), "pipeline[trim > upper] > maxlen(6)");
    let filters: Vec<Box<dyn Filter>> = vec![Box::new(Upper), Box::new(outer)];
    check_eq(filters[1].name(), "pipeline[pipeline[trim > upper] > maxlen(6)]");
    check_eq(filters.len(), 2);
});

